package com.paytaxihub.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="Transaction") public class Transaction { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Integer transactionId; @ManyToOne @JoinColumn(name="from_wallet_id") private Wallet fromWallet; @ManyToOne @JoinColumn(name="to_wallet_id") private Wallet toWallet; @ManyToOne @JoinColumn(name="trip_id") private Trip trip; @ManyToOne @JoinColumn(name="wallet_id") private Wallet wallet; @ManyToOne @JoinColumn(name="driver_id") private Driver driver; private BigDecimal amount; @Enumerated(EnumType.STRING) private TransactionType transactionType; @Enumerated(EnumType.STRING) private TransactionStatus transactionStatus; private String transactionReference; private LocalDateTime createdAt; public enum TransactionType{Payment,TopUp,Refund} public enum TransactionStatus{Pending,Completed,Failed} public Transaction(){} public Integer getTransactionId(){return transactionId;} public void setTransactionId(Integer v){transactionId=v;} public Trip getTrip(){return trip;} public void setTrip(Trip v){trip=v;} public Wallet getWallet(){return wallet;} public void setWallet(Wallet v){wallet=v;} public Wallet getFromWallet(){return fromWallet;} public void setFromWallet(Wallet v){fromWallet=v;} public Wallet getToWallet(){return toWallet;} public void setToWallet(Wallet v){toWallet=v;} public Driver getDriver(){return driver;} public void setDriver(Driver v){driver=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public TransactionType getTransactionType(){return transactionType;} public void setTransactionType(TransactionType v){transactionType=v;} public TransactionStatus getTransactionStatus(){return transactionStatus;} public void setTransactionStatus(TransactionStatus v){transactionStatus=v;} public String getTransactionReference(){return transactionReference;} public void setTransactionReference(String v){transactionReference=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
